import { MakeLogicType, actions, kea, key, listeners, path, props, reducers, selectors } from 'kea'
import { lazyLoaders } from 'kea-loaders'
import { urlToAction } from 'kea-router'

import { lemonToast } from '@posthog/lemon-ui'

import api, { ApiConfig } from 'lib/api'
import { urls } from 'scenes/urls'

import { hogFlowsBatchJobsCancelCreate } from 'products/workflows/frontend/generated/api'

import { HogFlowBatchJob } from './hogflows/types'

export interface BatchWorkflowJobsLogicProps {
    id?: string
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface batchWorkflowJobsLogicValues {
    batchWorkflowJobs: HogFlowBatchJob[] | null
    batchWorkflowJobsLoading: boolean
    cancellingJobIds: string[]
    jobs: HogFlowBatchJob[]
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface batchWorkflowJobsLogicActions {
    cancelBatchJob: (jobId: string) => {
        jobId: string
    }
    cancelBatchJobComplete: (jobId: string) => {
        jobId: string
    }
    loadBatchWorkflowJobs: () => any
    loadBatchWorkflowJobsFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadBatchWorkflowJobsSuccess: (
        batchWorkflowJobs: HogFlowBatchJob[] | null,
        payload?: any
    ) => {
        batchWorkflowJobs: HogFlowBatchJob[] | null
        payload?: any
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface batchWorkflowJobsLogicMeta {
    key: string
    __keaTypeGenInternalSelectorTypes: {
        jobs: (batchWorkflowJobs: HogFlowBatchJob[] | null) => HogFlowBatchJob[]
    }
}

export type batchWorkflowJobsLogicType = MakeLogicType<
    batchWorkflowJobsLogicValues,
    batchWorkflowJobsLogicActions,
    BatchWorkflowJobsLogicProps,
    batchWorkflowJobsLogicMeta
>

export const batchWorkflowJobsLogic = kea<batchWorkflowJobsLogicType>([
    path(['products', 'workflows', 'frontend', 'Workflows', 'batchWorkflowJobsLogic']),
    props({ id: 'new' } as BatchWorkflowJobsLogicProps),
    key((props) => props.id || 'new'),
    actions({
        cancelBatchJob: (jobId: string) => ({ jobId }),
        cancelBatchJobComplete: (jobId: string) => ({ jobId }),
    }),
    reducers({
        // Guards the Stop button against a second request while the first is in flight; the row
        // stays stoppable until the reload lands, so track cancels per job id and clear on finish.
        cancellingJobIds: [
            [] as string[],
            {
                cancelBatchJob: (state: string[], { jobId }: { jobId: string }) =>
                    state.includes(jobId) ? state : [...state, jobId],
                cancelBatchJobComplete: (state: string[], { jobId }: { jobId: string }) =>
                    state.filter((id) => id !== jobId),
            },
        ],
    }),
    lazyLoaders(({ props }) => ({
        batchWorkflowJobs: [
            null as HogFlowBatchJob[] | null,
            {
                loadBatchWorkflowJobs: async () => {
                    if (!props.id || props.id === 'new') {
                        return null
                    }

                    return api.hogFlows.getHogFlowBatchJobs(props.id)
                },
            },
        ],
    })),
    listeners(({ props, actions }) => ({
        cancelBatchJob: async ({ jobId }) => {
            if (!props.id || props.id === 'new') {
                actions.cancelBatchJobComplete(jobId)
                return
            }
            try {
                await hogFlowsBatchJobsCancelCreate(String(ApiConfig.getCurrentTeamId()), props.id, jobId)
                lemonToast.success(
                    'Batch run cancellation requested. Runs mid-step stop at their next step. Sent messages are not recalled.'
                )
                actions.loadBatchWorkflowJobs()
            } catch (e: any) {
                lemonToast.error(`Failed to stop the batch run: ${e?.detail ?? e?.message ?? String(e)}`)
            } finally {
                actions.cancelBatchJobComplete(jobId)
            }
        },
    })),
    selectors({
        jobs: [(s) => [s.batchWorkflowJobs], (batchWorkflowJobs: HogFlowBatchJob[] | null) => batchWorkflowJobs || []],
    }),
    urlToAction(({ props, actions }) => ({
        [urls.workflow(props.id || 'new', 'invocations')]: (_, __, ___, currentLocation, previousLocation) => {
            // Skip refetch on same-path URL changes — LogsViewer writes its search filter to the URL on every keystroke.
            if (!currentLocation.initial && currentLocation.pathname === previousLocation?.pathname) {
                return
            }
            actions.loadBatchWorkflowJobs()
        },
        [urls.workflow(props.id || 'new', 'metrics')]: (_, __, ___, currentLocation, previousLocation) => {
            if (!currentLocation.initial && currentLocation.pathname === previousLocation?.pathname) {
                return
            }
            actions.loadBatchWorkflowJobs()
        },
    })),
])
